facts = {"A", "B"}
rules = [({"A", "B"}, "C"),
         ({"C"}, "D"),
         ({"D", "B"}, "E")]

changed = True
while changed:
    changed = False
    for premises, conclusion in rules:
        if premises <= facts and conclusion not in facts:
            print(f"{' AND '.join(sorted(premises))} => {conclusion}")
            facts.add(conclusion)
            changed = True
print("Derived knowledge base:", sorted(facts))
